    fun getNiche(id: String): Niche {
        return allNiches.firstOrNull { it.id.equals(id, ignoreCase = true) } ?: defaultNiche
    }

    fun searchNiches(query: String): List<Niche> {
        if (query.isBlank()) return allNiches
        return allNiches.filter {
            it.name.contains(query, ignoreCase = true) ||
            it.category.contains(query, ignoreCase = true) ||
            it.promptAdvice.contains(query, ignoreCase = true)
        }
    }
